import time
from collections import deque

class DLQEnabledQueue:
    """Queue with retry counter and poison-message routing to a DLQ."""
    def __init__(self, name, max_retries=3, dlq=None):
        self.name = name
        self.max_retries = max_retries
        self.dlq = dlq or deque()
        self.messages = deque()       # (msg_id, payload, receive_count, headers)
        self.acked = set()

    def enqueue(self, msg_id, payload, headers=None):
        self.messages.append([msg_id, payload, 0, headers or {}])

    def dequeue(self):
        if not self.messages:
            return None
        m = self.messages[0]
        m[2] += 1                     # increment receive_count
        return m

    def ack(self, msg_id):
        self.acked.add(msg_id)
        self.messages = deque(m for m in self.messages if m[0] != msg_id)

    def nack_to_dlq(self, msg_id, reason):
        """Move a poison message to the DLQ with its failure history."""
        for m in list(self.messages):
            if m[0] == msg_id:
                m[3]["failure_reason"] = reason
                m[3]["original_queue"] = self.name
                m[3]["receive_count"] = m[2]
                m[3]["dlq_timestamp"] = time.time()
                self.messages.remove(m)
                self.dlq.append(m)
                print(f"[{self.name}] {msg_id} -> DLQ (reason: {reason}, "
                      f"attempts: {m[2]})")
                return

    def should_dlq(self, msg):
        """Decide: transient (retry) vs permanent (DLQ immediately)."""
        if msg[3].get("failure_type") == "permanent":
            return True               # schema/validation error -> DLQ now
        return msg[2] > self.max_retries

# Demo
q = DLQEnabledQueue("orders", max_retries=3)
q.enqueue("o1", {"user": "alice", "amt": 99})
q.enqueue("o2", "POISON_PERMANENT", {"failure_type": "permanent"})
q.enqueue("o3", "POISON_TRANSIENT")  # will exhaust retries

def try_process(msg):
    if "POISON_PERMANENT" == msg[1]:
        q.nack_to_dlq(msg[0], "schema_validation: not JSON")
    elif "POISON_TRANSIENT" == msg[1]:
        if msg[2] <= q.max_retries:
            print(f"  retry {msg[2]} for {msg[0]} (transient)")
        else:
            q.nack_to_dlq(msg[0], "timeout after 3 retries")
    else:
        print(f"  processed {msg[0]}: {msg[1]}")
        q.ack(msg[0])

# Process all messages; o1 acked, o2 immediate DLQ, o3 retried then DLQ
for _ in range(10):
    m = q.dequeue()
    if m: try_process(m)
    if not q.messages: break

print(f"\nDLQ contents:")
for m in q.dlq:
    print(f"  {m[0]}: reason={m[3].get('failure_reason')}, "
          f"attempts={m[3].get('receive_count')}")
